import React, { useState } from "react";
const Nav = () => {
  const [menuOpen, setMenuOpen] = useState(false);
  return (
    <nav>
      <div
        className={`burger ${menuOpen ? "open" : ""}`}
        onClick={setMenuOpen(true)}
      >
        <hr />
        <hr />
        <hr />
      </div>
      <h2>To-Do List</h2>
    </nav>
  );
};

export default Nav;
